/* Boldly Identity — the shared app markup (stage, rail, panels). Written in place so every tool is identical. */
document.write("\n\n  <!-- \u2500\u2500 STAGE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n  <div class=\"hty-stage\">\n    <div class=\"hty-tele\">\n      <div class=\"read\"><span class=\"lbl\" id=\"tl-a-l\">Unit</span><b id=\"tl-a\">\u2014</b></div>\n      <div class=\"read\"><span class=\"lbl\" id=\"tl-b-l\">Parts</span><b id=\"tl-b\">0</b></div>\n      <div class=\"read\"><span class=\"lbl\">Frame</span><b data-size-read>1920 \u00d7 1080</b></div>\n    </div>\n    <div class=\"hty-canvas\">\n      <div class=\"hty-frame\" id=\"frame\" data-w=\"1920\" data-h=\"1080\">\n        <canvas id=\"gl\"></canvas>\n        <svg id=\"art\" xmlns=\"http://www.w3.org/2000/svg\"></svg>\n      </div>\n    </div>\n    <div class=\"q-hint\">Double-click a letter to draw it</div>\n    <div class=\"q-hud\" id=\"hud\"></div>\n    <div class=\"q-toast\" id=\"toast\"></div>\n  </div>\n\n  <!-- \u2500\u2500 DOCK \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n  <div class=\"hty-dock\">\n\n    <div class=\"hty-rail\">\n      <div class=\"seg\" id=\"seg-render\" title=\"Render: flat geometry or lit (light, bloom, motion)\" style=\"margin-right:6px\"><button data-v=\"flat\">Flat</button><button data-v=\"lit\">Lit</button></div>\n      <button class=\"tab active\" data-tab=\"type\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M4 6h16M9 6v13\"/><path d=\"M15 19a4 4 0 0 1 4-4\"/></svg>Type</button>\n      <button class=\"tab\" data-tab=\"icons\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M12 20V11\"/><path d=\"M4 11a4 4 0 0 1 8 0a4 4 0 0 1 8 0\"/><path d=\"M4 11a8 8 0 0 0 8 9a8 8 0 0 0 8-9\" opacity=\".5\"/></svg>Icons</button>\n      <button class=\"tab\" data-tab=\"compose\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"1.5\"/><path d=\"M3 12h18\"/><path d=\"M8 12V3\" stroke-width=\"2.6\"/><path d=\"M8 12a7 7 0 0 1 7-7h6\"/></svg>Compose</button>\n      <button class=\"tab\" data-tab=\"data\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><circle cx=\"12\" cy=\"12\" r=\"8.5\" opacity=\".35\"/><path d=\"M12 3.5a8.5 8.5 0 0 1 8.5 8.5\" stroke-width=\"3.2\"/><path d=\"M12 7.5a4.5 4.5 0 1 0 4.5 4.5\"/></svg>Data</button>\n      <button class=\"tab\" data-tab=\"draw\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M3 9h18M3 15h18M9 3v18M15 3v18\" opacity=\".45\"/><path d=\"M9 15a6 6 0 0 1 6-6\" stroke-width=\"2.4\"/></svg>Draw</button>\n      <button class=\"tab\" data-tab=\"form\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M4 20a16 16 0 0 1 16-16\"/><path d=\"M9 20a11 11 0 0 1 11-11\"/></svg>Form</button>\n      <button class=\"tab\" data-tab=\"light\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v3M12 19v3M2 12h3M19 12h3M4.9 4.9l2.1 2.1M17 17l2.1 2.1M4.9 19.1L7 17M17 7l2.1-2.1\"/></svg>Light</button>\n      <button class=\"tab\" data-tab=\"motion\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 18c4 0 4-12 8-12s4 12 8 12\"/></svg>Motion</button>\n      <button class=\"tab\" data-tab=\"view\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><circle cx=\"12\" cy=\"12\" r=\"8.5\"/><path d=\"M12 3.5v17\" /><path d=\"M12 3.5a8.5 8.5 0 0 1 0 17z\" fill=\"currentColor\" stroke=\"none\"/></svg>View</button>\n      <button class=\"tab\" data-tab=\"export\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3v12m0 0l-4-4m4 4l4-4M5 21h14\"/></svg>Export</button>\n      <div class=\"sp\"></div>\n      <div class=\"hty-zoom\">\n        <button class=\"vbtn\" data-zoom=\"out\" title=\"Zoom out\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M5 12h14\"/></svg></button>\n        <b data-zoom-level>100%</b>\n        <button class=\"vbtn\" data-zoom=\"in\" title=\"Zoom in\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg></button>\n        <button class=\"vbtn\" data-zoom=\"reset\" title=\"Fit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8 3H5a2 2 0 0 0-2 2v3M16 3h3a2 2 0 0 1 2 2v3M8 21H5a2 2 0 0 1-2-2v-3M16 21h3a2 2 0 0 0 2-2v-3\"/></svg></button>\n      </div>\n    </div>\n\n    <div class=\"hty-panel\">\n      <div class=\"hty-panel-inner\">\n\n        <!-- \u2500\u2500 TYPE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n        <div class=\"panel-grid\" data-tab-panel=\"type\">\n          <div class=\"group\" id=\"scenes-group\" style=\"grid-column: 1 / -1\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linejoin=\"round\"><path d=\"M6 3h12v18l-6-4-6 4z\"/></svg><span class=\"lbl\">Scenes</span><span class=\"lbl\" id=\"pr-n\" style=\"margin-left:auto\"></span></div>\n            <div class=\"row\"><input type=\"text\" id=\"pr-name\" placeholder=\"Name this scene\u2026\" spellcheck=\"false\" /><button class=\"btn sm\" id=\"pr-save\" style=\"flex:0 0 auto\">Save</button></div>\n            <div id=\"pr-list\" style=\"display:flex;flex-direction:column;gap:5px\"></div>\n            <div class=\"btn-row\"><button class=\"btn ghost sm\" id=\"pr-export\">Export scenes</button><button class=\"btn ghost sm\" id=\"pr-import\">Import</button></div>\n            <input type=\"file\" id=\"pr-file\" accept=\".json,application/json\" class=\"hide\" />\n            <p class=\"note\">A scene stores everything on the canvas: text, spacing, weight, chosen variants, Flat / Lit, light, palette, grid, view (type \u00b7 icons \u00b7 compose), frame size, motion and export settings. Your glyph library stays shared across scenes. Kept in this browser across sessions.</p>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M4 7h16M4 12h11M4 17h7\"/></svg><span class=\"lbl\">Setting</span></div>\n            <div class=\"field\">\n              <div class=\"field-head\"><span class=\"name\">Text</span><span class=\"val\">\u21a9 new line</span></div>\n              <textarea id=\"txt\" spellcheck=\"false\"></textarea>\n            </div>\n            <div class=\"field\"><span class=\"name\">Specimen</span>\n              <div class=\"chips\" id=\"specimens\">\n                <button class=\"chip\" data-spec=\"od\">od</button>\n                <button class=\"chip\" data-spec=\"abc\">a\u2013z</button>\n                <button class=\"chip\" data-spec=\"num\">0\u20139</button>\n                <button class=\"chip\" data-spec=\"pan\">Pangram</button>\n              </div>\n            </div>\n            <div class=\"field\"><span class=\"name\">Align</span>\n              <div class=\"seg fill\" id=\"seg-align\"><button data-v=\"l\">Left</button><button data-v=\"c\">Centre</button><button data-v=\"r\">Right</button></div>\n            </div>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M5 5v14M5 12a7 7 0 0 1 7-7\"/><path d=\"M14 19V12a5 5 0 0 1 5-5\" opacity=\".5\"/></svg><span class=\"lbl\">Alternates</span></div>\n            <div id=\"alts\" style=\"display:flex;flex-direction:column;gap:9px\"></div>\n            <p class=\"note\" id=\"alts-note\"></p>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M4 4v16M20 4v16M8 12h8m0 0l-2.5-2.5M16 12l-2.5 2.5M8 12l2.5-2.5M8 12l2.5 2.5\"/></svg><span class=\"lbl\">Spacing</span></div>\n            <div class=\"switch\" id=\"f-tsnap\"><span class=\"name\">Snap tracking to grid</span><div class=\"track-sw\" id=\"sw-tsnap\"></div></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Tracking</span><span class=\"val num\" data-read=\"track\"></span></div><input type=\"range\" data-k=\"track\" min=\"-1\" max=\"4\" step=\"0.05\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Leading</span><span class=\"val num\" data-read=\"lead\"></span></div><input type=\"range\" data-k=\"lead\" min=\"-3\" max=\"8\" step=\"0.1\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Word space</span><span class=\"val num\" data-read=\"space\"></span></div><input type=\"range\" data-k=\"space\" min=\"0\" max=\"6\" step=\"0.25\" /></div>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M8 3v18M3 8h18\" opacity=\".5\"/></svg><span class=\"lbl\">Scale</span></div>\n            <div class=\"switch\"><span class=\"name\">Fit to frame</span><div class=\"track-sw\" id=\"sw-fit\"></div></div>\n            <div class=\"field\" id=\"f-sysmargin\"><div class=\"field-head\"><span class=\"name\">Margin</span><span class=\"val num\" data-read=\"sysMargin\"></span></div><input type=\"range\" data-k=\"sysMargin\" min=\"0\" max=\"12\" step=\"1\" /></div>\n            <div class=\"field\" id=\"f-margin\"><div class=\"field-head\"><span class=\"name\">Margin</span><span class=\"val num\" data-read=\"margin\"></span></div><input type=\"range\" data-k=\"margin\" min=\"0\" max=\"0.3\" step=\"0.005\" /></div>\n            <div class=\"field\" id=\"f-unit\"><div class=\"field-head\"><span class=\"name\">Unit</span><span class=\"val num\" data-read=\"unit\"></span></div><input type=\"range\" data-k=\"unit\" min=\"6\" max=\"220\" step=\"1\" /></div>\n          </div>\n        </div>\n\n        <!-- \u2500\u2500 FORM \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n        <div class=\"panel-grid\" data-tab-panel=\"form\" style=\"display:none\">\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M5 19a14 14 0 0 1 14-14\"/><path d=\"M11 19a8 8 0 0 1 8-8\"/></svg><span class=\"lbl\">Stroke</span></div>\n            <div class=\"switch\"><span class=\"name\">Grid system</span><div class=\"track-sw\" id=\"sw-sys\"></div></div>\n            <p class=\"note\" id=\"sys-note\"></p>\n            <div class=\"switch\" id=\"f-arccaps\"><span class=\"name\">Square arc ends</span><div class=\"track-sw\" id=\"sw-arccaps\"></div></div>\n            <div class=\"switch\" id=\"f-gaplink\"><span class=\"name\">Stencil gap = grid gap</span><div class=\"track-sw\" id=\"sw-gaplink\"></div></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Weight</span><span class=\"val num\" data-read=\"t\"></span></div><input type=\"range\" data-k=\"t\" min=\"0.05\" max=\"3\" step=\"0.01\" /></div>\n            <div class=\"field\" id=\"f-gap\"><div class=\"field-head\"><span class=\"name\">Gap</span><span class=\"val num\" data-read=\"g\"></span></div><input type=\"range\" data-k=\"g\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Lanes</span><span class=\"val num\" data-read=\"lanes\"></span></div><input type=\"range\" data-k=\"lanes\" min=\"1\" max=\"8\" step=\"1\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Lane gap</span><span class=\"val num\" data-read=\"laneGap\"></span></div><input type=\"range\" data-k=\"laneGap\" min=\"0.005\" max=\"0.4\" step=\"0.005\" /></div>\n            <div class=\"field\" id=\"f-side\"><span class=\"name\">Stroke side</span>\n              <div class=\"seg fill\" id=\"seg-side\"><button data-v=\"draw\">As drawn</button><button data-v=\"-1\">In</button><button data-v=\"0\">Mid</button><button data-v=\"1\">Out</button></div>\n              <p class=\"note\">Where the weight sits relative to each path. <b style=\"font-weight:500\">In</b> keeps every letter inside its grid box.</p>\n            </div>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M4 12h6M14 12h6M12 4v5M12 15v5\"/></svg><span class=\"lbl\">Joins</span></div>\n            <div class=\"field\"><span class=\"name\">Cut the gap at</span>\n              <div class=\"chips multi\" id=\"chips-gap\">\n                <button class=\"chip\" data-k=\"gapAA\">Arc \u00b7 Arc</button>\n                <button class=\"chip\" data-k=\"gapAL\">Arc \u00b7 Line</button>\n                <button class=\"chip\" data-k=\"gapLL\">Line \u00b7 Line</button>\n                <button class=\"chip\" data-k=\"gapT\">Corners \u00b7 Tees</button>\n              </div>\n            </div>\n            <div class=\"field\"><span class=\"name\">Corner priority</span>\n              <div class=\"seg fill\" id=\"seg-prio\"><button data-v=\"v\">Vertical</button><button data-v=\"h\">Horizontal</button></div>\n              <p class=\"note\">Which stroke runs through when two lines meet at a corner.</p>\n            </div>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"3\"/><circle cx=\"9\" cy=\"9\" r=\"1.2\" fill=\"currentColor\"/><circle cx=\"15\" cy=\"15\" r=\"1.2\" fill=\"currentColor\"/><circle cx=\"15\" cy=\"9\" r=\"1.2\" fill=\"currentColor\"/><circle cx=\"9\" cy=\"15\" r=\"1.2\" fill=\"currentColor\"/></svg><span class=\"lbl\">Explore</span></div>\n            <div class=\"btn-row\"><button class=\"btn ghost sm\" id=\"btn-shuffle\">Shuffle form</button><button class=\"btn ghost sm\" id=\"btn-form-reset\">Reset form</button></div>\n            <p class=\"note\">Shuffle keeps your glyphs and randomises weight, gap, side and joins within a sane range. <span class=\"kbd\">\u2318Z</span> steps back.</p>\n          </div>\n        </div>\n\n        <!-- \u2500\u2500 MOTION \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n        <div class=\"panel-grid\" data-tab-panel=\"motion\" style=\"display:none\">\n          <div class=\"group\" style=\"grid-column: 1 / -1\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linejoin=\"round\"><path d=\"M6 3h12v18l-6-4-6 4z\"/></svg><span class=\"lbl\">Saved motions</span><span class=\"lbl\" id=\"mp-n\" style=\"margin-left:auto\"></span></div>\n            <div class=\"row\"><input type=\"text\" id=\"mp-name\" placeholder=\"Name this motion\u2026\" spellcheck=\"false\" /><button class=\"btn sm\" id=\"mp-save\" style=\"flex:0 0 auto\">Save</button></div>\n            <div id=\"mp-list\" style=\"display:flex;flex-direction:column;gap:5px\"></div>\n            <div class=\"btn-row\"><button class=\"btn ghost sm\" id=\"mp-export\">Export motions</button><button class=\"btn ghost sm\" id=\"mp-import\">Import</button></div>\n            <input type=\"file\" id=\"mp-file\" accept=\".json,application/json\" class=\"hide\" />\n            <p class=\"note\">A motion keeps the keyframes (weight, spacing and each keyframe's own letterforms), duration, hold, easing, loop and the text. Kept in this browser across sessions.</p>\n          </div>\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 18c4 0 4-12 8-12s4 12 8 12\"/><circle cx=\"4\" cy=\"18\" r=\"1.4\" fill=\"currentColor\"/><circle cx=\"12\" cy=\"6\" r=\"1.4\" fill=\"currentColor\"/><circle cx=\"20\" cy=\"18\" r=\"1.4\" fill=\"currentColor\"/></svg><span class=\"lbl\">Motion</span></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Keyframes</span><span class=\"val\">weight \u00b7 spacing</span></div>\n              <div class=\"chips kf\" id=\"kf\"></div>\n            </div>\n            <div class=\"btn-row\"><button class=\"btn ghost sm\" id=\"kf-add\">+ Add current</button><button class=\"btn ghost sm\" id=\"kf-upd\">Update</button><button class=\"btn ghost sm\" id=\"kf-del\">Delete</button></div>\n            <div class=\"kf-play\"><button class=\"icon-btn\" id=\"kf-play\" title=\"Play / pause  (P)\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M7 4l13 8-13 8z\"/></svg></button><input type=\"range\" id=\"kf-scrub\" min=\"0\" max=\"1000\" step=\"1\" value=\"0\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Duration per step</span><span class=\"val num\" data-mread=\"dur\"></span></div><input type=\"range\" data-mk=\"dur\" min=\"0.2\" max=\"8\" step=\"0.1\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Hold on keyframe</span><span class=\"val num\" data-mread=\"hold\"></span></div><input type=\"range\" data-mk=\"hold\" min=\"0\" max=\"0.9\" step=\"0.01\" /></div>\n            <div class=\"field\"><span class=\"name\">Easing</span>\n              <div class=\"seg fill\" id=\"seg-ease\"><button data-v=\"lin\">Linear</button><button data-v=\"smooth\">Smooth</button><button data-v=\"expo\">Expo</button></div>\n            </div>\n            <div class=\"field\"><span class=\"name\">Loop</span>\n              <div class=\"seg fill\" id=\"seg-loop\"><button data-v=\"ping\">Ping-pong</button><button data-v=\"loop\">Cycle</button></div>\n            </div>\n            <p class=\"note\">Click a keyframe to load it, adjust weight / tracking, or click letters on the canvas to pick other glyph variants, then Update. Each keyframe keeps its own frozen copy of the letterforms, so editing one end never touches the other; Aa marks keyframes whose letters differ; they morph smoothly \u2014 arcs change radius, lines slide and stretch, extra parts retract into the stroke they hang from. Text size locks to the widest keyframe while playing.</p>\n          </div>\n        </div>\n\n        <!-- \u2500\u2500 DRAW \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n        <div class=\"panel-grid\" data-tab-panel=\"draw\" style=\"display:none\">\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2\"/><path d=\"M4 9h16M4 16h16\" opacity=\".5\"/></svg><span class=\"lbl\">Glyph</span></div>\n            <div class=\"ghead\">\n              <div class=\"big\" id=\"g-big\">a</div>\n              <div class=\"meta\"><b id=\"g-name\">a \u00b7 lowercase</b><span class=\"lbl\" id=\"g-sub\">4 parts \u00b7 width 4u</span></div>\n            </div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Variants</span><span class=\"val\" id=\"g-vnote\"></span></div>\n              <div class=\"chips\" id=\"g-vars\"></div>\n            </div>\n            <div class=\"field\"><span class=\"name\">Advance width</span>\n              <div class=\"stepper\"><button data-wstep=\"-0.5\">\u2212</button><div class=\"vs\"></div><input type=\"number\" id=\"g-w\" step=\"0.5\" min=\"0\" /><div class=\"vs\"></div><button data-wstep=\"0.5\">+</button></div>\n            </div>\n            <div class=\"btn-row\">\n              <button class=\"btn ghost sm\" id=\"g-mirror\" title=\"Mirror left \u2194 right\">Mirror \u2194</button>\n              <button class=\"btn ghost sm\" id=\"g-flip\" title=\"Flip around the x-height centre (b \u2194 p)\">Flip \u2195</button>\n            </div>\n            <div class=\"btn-row\">\n              <button class=\"btn ghost sm\" id=\"g-clear\">Clear</button>\n              <button class=\"btn ghost sm\" id=\"g-revert\">Revert</button>\n            </div>\n            <div class=\"btn-row\"><button class=\"btn ghost sm\" id=\"g-align\" title=\"Give every line the stroke side of the arc or line it joins\">Align joins</button><button class=\"btn ghost sm\" id=\"g-alignall\">Align all glyphs</button></div>\n            <button class=\"btn ghost sm hide\" id=\"g-fromlower\" style=\"justify-content:center\">Start from lowercase</button>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"><path d=\"M5 3l7 17 2.5-6.5L21 11z\"/></svg><span class=\"lbl\">Tool</span></div>\n            <div class=\"seg fill\" id=\"seg-tool\"><button data-v=\"arc\">Arc<span class=\"k\">A</span></button><button data-v=\"line\">Line<span class=\"k\">L</span></button><button data-v=\"select\">Edit<span class=\"k\">V</span></button><button data-v=\"erase\">Erase<span class=\"k\">E</span></button></div>\n            <div class=\"field\"><span class=\"name\">Arc radius</span>\n              <div class=\"seg fill\" id=\"seg-rad\"><button data-v=\"0.5\">\u00bd</button><button data-v=\"1\">1</button><button data-v=\"2\">2</button><button data-v=\"3\">3</button><button data-v=\"4\">4</button></div>\n              <div class=\"rad-step\"><button class=\"btn ghost sm\" id=\"rad-dn\" title=\"Smaller radius  (\u2325\u2193 or \u2212)\">\u25bc</button><span class=\"num\" id=\"rad-v\"></span><button class=\"btn ghost sm\" id=\"rad-up\" title=\"Bigger radius  (\u2325\u2191 or +)\">\u25b2</button></div>\n            </div>\n            <div class=\"field\"><span class=\"name\">Arc side</span>\n              <div class=\"seg fill\" id=\"seg-aside\"><button data-v=\"-1\">Inside</button><button data-v=\"0\">Centre</button><button data-v=\"1\">Outside</button></div>\n            </div>\n            <div class=\"field\"><span class=\"name\">Snap</span>\n              <div class=\"seg fill\" id=\"seg-res\"><button data-v=\"1\">1 unit</button><button data-v=\"0.5\">\u00bd unit</button></div>\n            </div>\n            <p class=\"note\" id=\"tool-note\"></p>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2\" stroke-dasharray=\"3 3\"/></svg><span class=\"lbl\">Selection</span></div>\n            <div id=\"insp-empty\" class=\"note\">Pick <b style=\"font-weight:500\">Edit</b> and click a part to inspect it. Drag to move \u00b7 \u21e7-click or drag a box to select more \u00b7 \u2325/\u2318-drag duplicates \u00b7 <span class=\"kbd\">\u2318C</span> <span class=\"kbd\">\u2318X</span> <span class=\"kbd\">\u2318V</span> <span class=\"kbd\">\u2318D</span> <span class=\"kbd\">\u2318A</span> \u00b7 <span class=\"kbd\">\u2325\u2191\u2193</span> or <span class=\"kbd\">+ \u2212</span> radius \u00b7 <span class=\"kbd\">S</span> side \u00b7 <span class=\"kbd\">R</span> rotate \u00b7 <span class=\"kbd\">\u232b</span> delete.</div>\n            <div class=\"insp hide\" id=\"insp\">\n              <div class=\"top\"><span class=\"name\" id=\"insp-kind\">Arc</span><span class=\"val num\" id=\"insp-pos\"></span></div>\n              <div class=\"field\"><span class=\"name\">Side</span>\n                <div class=\"seg fill\" id=\"seg-pside\"><button data-v=\"-1\">In / L / Up</button><button data-v=\"0\">Centre</button><button data-v=\"1\">Out / R / Dn</button></div>\n              </div>\n              <div class=\"field\" id=\"insp-rad\"><span class=\"name\">Radius</span>\n                <div class=\"seg fill\" id=\"seg-prad\"><button data-v=\"0.5\">\u00bd</button><button data-v=\"1\">1</button><button data-v=\"2\">2</button><button data-v=\"3\">3</button><button data-v=\"4\">4</button></div>\n                <div class=\"rad-step\"><button class=\"btn ghost sm\" id=\"prad-dn\" title=\"Smaller radius  (\u2325\u2193 or \u2212)\">\u25bc</button><span class=\"num\" id=\"prad-v\"></span><button class=\"btn ghost sm\" id=\"prad-up\" title=\"Bigger radius  (\u2325\u2191 or +)\">\u25b2</button></div>\n              </div>\n              <div class=\"btn-row\"><button class=\"btn ghost sm\" id=\"insp-rot\">Rotate</button><button class=\"btn ghost sm\" id=\"insp-del\">Delete</button></div>\n            </div>\n          </div>\n\n          <div class=\"group\" style=\"grid-column: 1 / -1\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 12a9 9 0 1 0 3-6.7L3 8\"/><path d=\"M3 3v5h5M12 7v5l3 2\"/></svg><span class=\"lbl\">Form history</span><span class=\"lbl\" id=\"g-histn\" style=\"margin-left:auto\"></span></div>\n            <div class=\"gmap\" id=\"g-hist\"></div>\n            <p class=\"note\">Every form this letter has had is kept automatically. Click to bring one back \u00b7 \u2325-click to keep it as a new variant.</p>\n          </div>\n\n          <div class=\"group\" style=\"grid-column: 1 / -1\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\"/></svg><span class=\"lbl\">Glyph map</span><span class=\"lbl\" style=\"margin-left:auto\">, . to step</span></div>\n            <div class=\"gmap\" id=\"gmap\"></div>\n          </div>\n        </div>\n\n        <!-- \u2500\u2500 COMPOSE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n        <div class=\"panel-grid\" data-tab-panel=\"compose\" style=\"display:none\">\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M3 9h18M3 15h18M9 3v18M15 3v18\"/></svg><span class=\"lbl\">Grid</span></div>\n            <button class=\"btn\" id=\"c-shuffle\" style=\"justify-content:center;width:100%\" title=\"Redistribute the shapes \u2014 stroke, grid and format stay  (N)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 3h5v5M4 20L21 3M21 16v5h-5M15 15l6 6M4 4l5 5\"/></svg>Shuffle shapes</button>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Columns</span><span class=\"val num\" data-cread=\"cols\"></span></div><input type=\"range\" data-ck=\"cols\" min=\"1\" max=\"16\" step=\"1\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Stroke</span><span class=\"val num\" id=\"c-strokeval\"></span></div><input type=\"range\" id=\"c-stroke\" min=\"0\" max=\"15\" step=\"1\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Gap</span><span class=\"val num\" data-cread=\"gap\"></span></div><input type=\"range\" data-ck=\"gap\" min=\"0\" max=\"60\" step=\"1\" /></div>\n            <div class=\"field\"><span class=\"name\">Margin</span>\n              <div class=\"seg fill\" id=\"seg-cmargin\"><button data-v=\"0\">0</button><button data-v=\"1\">1\u00d7 gap</button><button data-v=\"2\">2\u00d7</button><button data-v=\"3\">3\u00d7</button></div>\n            </div>\n            <div class=\"field\"><span class=\"name\">Target format</span>\n              <div class=\"hty-select\" id=\"c-fmt\">\n                <button class=\"hty-select-btn\"><span class=\"hty-select-val\">1080 \u00d7 1350 \u00b7 4:5</span><svg class=\"hty-select-chev\" viewBox=\"0 0 12 8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M1 2l5 4 5-4\"/></svg></button>\n                <div class=\"hty-select-menu\" role=\"listbox\"><button class=\"hty-opt\" data-value=\"1080x1080\">1080 \u00d7 1080 \u00b7 1:1</button><button class=\"hty-opt\" data-value=\"1080x1350\">1080 \u00d7 1350 \u00b7 4:5</button><button class=\"hty-opt\" data-value=\"1080x1440\">1080 \u00d7 1440 \u00b7 3:4</button><button class=\"hty-opt\" data-value=\"1080x1920\">1080 \u00d7 1920 \u00b7 9:16</button><button class=\"hty-opt\" data-value=\"1920x1080\">1920 \u00d7 1080 \u00b7 16:9</button><button class=\"hty-opt\" data-value=\"2048x2048\">2048 \u00d7 2048 \u00b7 1:1</button><button class=\"hty-opt\" data-value=\"2480x3508\">2480 \u00d7 3508 \u00b7 A4 300dpi</button><button class=\"hty-opt\" data-value=\"custom\">Custom\u2026</button></div>\n              </div>\n            </div>\n            <div class=\"tf-row\" id=\"c-fmt-custom\">\n              <label class=\"tf\"><span class=\"g\">W</span><input type=\"number\" id=\"c-fw\" data-scrub=\"2\" data-min=\"64\" data-step=\"1\" /></label>\n              <label class=\"tf\"><span class=\"g\">H</span><input type=\"number\" id=\"c-fh\" data-scrub=\"2\" data-min=\"64\" data-step=\"1\" /></label>\n            </div>\n            <div class=\"switch\"><span class=\"name\">Fit format to grid</span><div class=\"track-sw\" data-csw=\"lock\"></div></div>\n            <div class=\"field-head\"><span class=\"name\">Fitted</span><span class=\"val num\" id=\"c-fitted\"></span></div>\n            <button class=\"btn ghost sm\" id=\"c-bestcols\" style=\"justify-content:center\">Find closest grid</button>\n            <div class=\"switch\"><span class=\"name\">Show cells</span><div class=\"track-sw\" data-csw=\"cells\"></div></div>\n            <p class=\"note\" id=\"c-gridnote\"></p>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M4 20V14a10 10 0 0 1 10-10h6\"/></svg><span class=\"lbl\">Vocabulary</span></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Arcs</span><span class=\"val num\" data-cread=\"wArc\"></span></div><input type=\"range\" data-ck=\"wArc\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Stems</span><span class=\"val num\" data-cread=\"wStem\"></span></div><input type=\"range\" data-ck=\"wStem\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Rails</span><span class=\"val num\" data-cread=\"wRail\"></span></div><input type=\"range\" data-ck=\"wRail\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Solids</span><span class=\"val num\" data-cread=\"wSolid\"></span></div><input type=\"range\" data-ck=\"wSolid\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Empty</span><span class=\"val num\" data-cread=\"wEmpty\"></span></div><input type=\"range\" data-ck=\"wEmpty\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">2\u00d7 arcs</span><span class=\"val num\" data-cread=\"big2\"></span></div><input type=\"range\" data-ck=\"big2\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">3\u00d7 arcs</span><span class=\"val num\" data-cread=\"big3\"></span></div><input type=\"range\" data-ck=\"big3\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M3 18a6 6 0 0 1 6-6h6a6 6 0 0 0 6-6\"/></svg><span class=\"lbl\">Flow</span></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Continuity</span><span class=\"val num\" data-cread=\"cont\"></span></div><input type=\"range\" data-ck=\"cont\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Window X</span><span class=\"val num\" data-cread=\"offX\"></span></div><input type=\"range\" data-ck=\"offX\" min=\"-20\" max=\"20\" step=\"1\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Window Y</span><span class=\"val num\" data-cread=\"offY\"></span></div><input type=\"range\" data-ck=\"offY\" min=\"-20\" max=\"20\" step=\"1\" /></div>\n            <div class=\"field\"><span class=\"name\">Seed</span>\n              <div class=\"row\"><div class=\"stepper\"><button data-cseed=\"-1\">\u2212</button><div class=\"vs\"></div><input type=\"number\" id=\"c-seed\" /><div class=\"vs\"></div><button data-cseed=\"1\">+</button></div><button class=\"icon-btn\" id=\"c-dice\" title=\"New seed  (N)\" style=\"flex:0 0 38px\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 3h5v5M4 20L21 3M21 16v5h-5M15 15l6 6M4 4l5 5\"/></svg></button></div>\n            </div>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"><path d=\"M5 3l7 17 2.5-6.5L21 11z\"/></svg><span class=\"lbl\">Edit cells</span></div>\n            <div class=\"seg fill\" id=\"seg-ctool\"><button data-v=\"rotate\">Turn<span class=\"k\">R</span></button><button data-v=\"swap\">Swap<span class=\"k\">S</span></button><button data-v=\"erase\">Erase<span class=\"k\">E</span></button></div>\n            <p class=\"note\" id=\"ctool-note\"></p>\n            <div class=\"btn-row\"><button class=\"btn ghost sm\" id=\"c-clear\">Clear edits</button><button class=\"btn ghost sm\" id=\"c-reset\">Reset compose</button></div>\n          </div>\n          <div class=\"group\" style=\"grid-column: 1 / -1\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 18c4 0 4-12 8-12s4 12 8 12\"/></svg><span class=\"lbl\">Motion</span></div>\n            <div class=\"switch\"><span class=\"name\">Animate the tiles</span><div class=\"track-sw\" id=\"sw-cm\"></div></div>\n            <div class=\"play-row\"><button class=\"icon-btn\" id=\"cm-play\" title=\"Play / pause  (P)\"></button><input type=\"range\" id=\"cm-scrub\" min=\"0\" max=\"1000\" step=\"1\" value=\"0\" /></div>\n            <div class=\"field\"><span class=\"name\">Moves</span>\n              <div class=\"chips multi\"><button class=\"chip\" data-cmmove=\"turn\">Turn</button><button class=\"chip\" data-cmmove=\"slide\">Slide</button><button class=\"chip\" data-cmmove=\"grow\">Grow</button><button class=\"chip\" data-cmmove=\"breathe\">Breathe</button></div>\n            </div>\n            <div class=\"field\"><span class=\"name\">Flow</span><div class=\"seg fill\" data-cmseg=\"pattern\"><button data-v=\"wave\">Wave</button><button data-v=\"ripple\">Ripple</button><button data-v=\"random\">Random</button></div></div>\n            <div class=\"field\"><span class=\"name\">Tempo</span><div class=\"seg fill\" data-cmseg=\"tempo\"><button data-v=\"1\">Slow</button><button data-v=\"2\">Medium</button><button data-v=\"4\">Fast</button></div></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Amount</span><span class=\"val num\" data-cmread=\"amount\"></span></div><input type=\"range\" data-cmk=\"amount\" min=\"0.05\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Snap</span><span class=\"val num\" data-cmread=\"snap\"></span></div><input type=\"range\" data-cmk=\"snap\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n            <button class=\"btn ghost sm\" id=\"cm-seed\" style=\"justify-content:center;width:100%\" title=\"Another set of tiles moves\">Shuffle</button>\n          </div>\n        </div>\n\n<!-- \u2500\u2500 ICONS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n        <div class=\"panel-grid\" data-tab-panel=\"icons\" style=\"display:none\">\n          <div class=\"group\" style=\"grid-column: 1 / -1\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\"/></svg><span class=\"lbl\">Icon library</span><span class=\"lbl\" id=\"icon-n\" style=\"margin-left:auto\"></span></div>\n            <div class=\"gmap\" id=\"icon-map\"></div>\n            <p class=\"note\">Click an icon to select it \u00b7 double-click (or Edit) to draw it. Icons use the same arcs, lines, weight, gap and grid system as the letters.</p>\n            <div class=\"btn-row\"><button class=\"btn sm\" id=\"icon-edit\">Edit in Draw</button><button class=\"btn ghost sm\" id=\"icon-dup\">Duplicate</button></div>\n            <div class=\"btn-row\"><button class=\"btn ghost sm\" id=\"icon-ren\">Rename</button><button class=\"btn ghost sm\" id=\"icon-del\">Delete</button></div>\n            <button class=\"btn ghost sm\" id=\"icon-files\" style=\"justify-content:center;width:100%\" title=\"One transparent SVG per icon, named after it\">Export every icon as SVG</button>\n          </div>\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg><span class=\"lbl\">New icon</span></div>\n            <div class=\"row\"><input type=\"text\" id=\"icon-name\" placeholder=\"Name\u2026\" spellcheck=\"false\" /><button class=\"btn sm\" id=\"icon-new\" style=\"flex:0 0 auto\">Create</button></div>\n            <div class=\"field\"><span class=\"name\">Grid</span>\n              <div class=\"seg fill\" id=\"seg-igrid\"><button data-v=\"8\">8</button><button data-v=\"12\">12</button><button data-v=\"16\">16</button><button data-v=\"24\">24</button></div>\n            </div>\n          </div>\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M3 9h18M3 15h18M9 3v18M15 3v18\"/></svg><span class=\"lbl\">Sheet</span></div>\n            <div class=\"field\"><span class=\"name\">Show</span>\n              <div class=\"seg fill\" id=\"seg-ishow\"><button data-v=\"all\">All icons</button><button data-v=\"current\">Selected</button></div>\n            </div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Columns</span><span class=\"val num\" data-iread=\"cols\"></span></div><input type=\"range\" data-ik=\"cols\" min=\"0\" max=\"12\" step=\"1\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Spacing</span><span class=\"val num\" data-iread=\"gap\"></span></div><input type=\"range\" data-ik=\"gap\" min=\"0\" max=\"8\" step=\"0.5\" /></div>\n          </div>\n        </div>\n\n        <!-- \u2500\u2500 DATA \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n        <div class=\"panel-grid\" data-tab-panel=\"data\" style=\"display:none\">\n          <div class=\"group\" style=\"grid-column: 1 / -1\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><circle cx=\"12\" cy=\"12\" r=\"8.5\" opacity=\".35\"/><path d=\"M12 3.5a8.5 8.5 0 0 1 8.5 8.5\" stroke-width=\"3.2\"/><path d=\"M12 7.5a4.5 4.5 0 1 0 4.5 4.5\"/></svg><span class=\"lbl\">Chart</span></div>\n            <div class=\"chips\" id=\"d-charts\"></div>\n            <p class=\"note\" id=\"d-note\"></p>\n          </div>\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M4 20V10M10 20V4M16 20v-7M22 20H2\"/></svg><span class=\"lbl\">Values</span></div>\n            <textarea id=\"d-src\" spellcheck=\"false\" rows=\"6\" placeholder=\"72&#10;41&#10;18\"></textarea>\n            <p class=\"note\">One number per line (anything else on the line is ignored).</p>\n            <div class=\"field\"><span class=\"name\">Values are</span>\n              <div class=\"seg fill\" id=\"seg-dscale\"><button data-v=\"pct\">Percentages</button><button data-v=\"max\">Amounts</button></div>\n            </div>\n            <div class=\"btn-row\"><button class=\"btn ghost sm\" id=\"d-rand\" title=\"New random values  (N)\">Random values</button><button class=\"btn ghost sm\" id=\"d-seed\" title=\"Another fill of arcs and lines (Curves, Field)\">Shuffle tiles</button></div>\n          </div>\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M3 9h18M3 15h18M9 3v18M15 3v18\"/></svg><span class=\"lbl\">Form</span></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Size</span><span class=\"val num\" data-dread=\"size\"></span></div><input type=\"range\" data-dk=\"size\" min=\"0.3\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Cells (100%)</span><span class=\"val num\" data-dread=\"res\"></span></div><input type=\"range\" data-dk=\"res\" min=\"4\" max=\"24\" step=\"1\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Thickness</span><span class=\"val num\" data-dread=\"thick\"></span></div><input type=\"range\" data-dk=\"thick\" min=\"0.04\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Gap</span><span class=\"val num\" data-dread=\"gap\"></span></div><input type=\"range\" data-dk=\"gap\" min=\"0\" max=\"4\" step=\"0.1\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Corner</span><span class=\"val num\" data-dread=\"radius\"></span></div><input type=\"range\" data-dk=\"radius\" min=\"0\" max=\"8\" step=\"0.5\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Track</span><span class=\"val num\" data-dread=\"trackTone\"></span></div><input type=\"range\" data-dk=\"trackTone\" min=\"0\" max=\"0.6\" step=\"0.01\" /></div>\n            <div class=\"field\"><span class=\"name\">Tones</span>\n              <div class=\"seg fill\" id=\"seg-dtones\"><button data-v=\"ramp\">Ramp</button><button data-v=\"accent\">Accent</button><button data-v=\"mono\">Mono</button></div>\n            </div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Grid</span><span class=\"val num\" data-dread=\"grid\"></span></div><input type=\"range\" data-dk=\"grid\" min=\"16\" max=\"96\" step=\"2\" /></div>\n            <div class=\"switch\"><span class=\"name\">Cut every cell</span><div class=\"track-sw\" id=\"sw-dcuts\"></div></div>\n            <div class=\"switch\"><span class=\"name\">Area-true (rings)</span><div class=\"track-sw\" id=\"sw-darea\"></div></div>\n          </div>\n        </div>\n\n        <!-- \u2500\u2500 LIGHT \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n        <div class=\"panel-grid\" data-tab-panel=\"light\" style=\"display:none\">\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M5 12a7 7 0 0 1 14 0\"/><path d=\"M12 5v14\" opacity=\".5\"/></svg><span class=\"lbl\">Looks</span></div>\n            \n            <div class=\"chips\" id=\"looks\"></div>\n            <div class=\"chips\" id=\"quick-pal\"></div>\n            <div class=\"play-row\"><button class=\"icon-btn\" id=\"play\" title=\"Play / pause  (P)\"></button><input type=\"range\" id=\"scrub\" min=\"0\" max=\"1000\" step=\"1\" value=\"0\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Loop length</span><span class=\"val num\" data-lread=\"dur\"></span></div><input type=\"range\" data-lk=\"dur\" min=\"2\" max=\"30\" step=\"0.5\" /></div>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><circle cx=\"8\" cy=\"9\" r=\"3\"/><path d=\"M16 4v16\"/><path d=\"M4 20a8 8 0 0 1 8-8\" opacity=\".6\"/></svg><span class=\"lbl\">Light sources</span></div>\n            <div class=\"field\"><span class=\"name\">Motion</span>\n              <div class=\"seg fill\" id=\"seg-motion\"><button data-v=\"sweep\">Sweep \u00b7 light bar</button><button data-v=\"drift\">Drift</button></div>\n            </div>\n            <div data-mcase=\"sweep\" style=\"display:flex;flex-direction:column;gap:11px\">\n              <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Bars</span><span class=\"val num\" data-lread=\"bars\"></span></div><input type=\"range\" data-lk=\"bars\" min=\"1\" max=\"4\" step=\"1\" /></div>\n              <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Angle</span><span class=\"val num\" data-lread=\"angle\"></span></div><input type=\"range\" data-lk=\"angle\" min=\"-90\" max=\"90\" step=\"1\" /></div>\n              <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Passes per loop</span><span class=\"val num\" data-lread=\"passes\"></span></div><input type=\"range\" data-lk=\"passes\" min=\"1\" max=\"4\" step=\"1\" /></div>\n              <div class=\"field\"><span class=\"name\">Direction</span><div class=\"seg fill\" id=\"seg-dir\"><button data-v=\"1\">Forward</button><button data-v=\"-1\">Back</button></div></div>\n            </div>\n            <div class=\"field\" data-mcase=\"drift\"><span class=\"name\">Shapes</span>\n              <div class=\"seg fill\" id=\"seg-kinds\"><button data-v=\"mixed\">Mixed</button><button data-v=\"bars\">Bars</button><button data-v=\"rings\">Rings</button><button data-v=\"discs\">Discs</button></div>\n            </div>\n            <div class=\"field\" data-mcase=\"drift\"><div class=\"field-head\"><span class=\"name\">Count</span><span class=\"val num\" data-lread=\"count\"></span></div><input type=\"range\" data-lk=\"count\" min=\"1\" max=\"8\" step=\"1\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Size</span><span class=\"val num\" data-lread=\"size\"></span></div><input type=\"range\" data-lk=\"size\" min=\"0.05\" max=\"1.2\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Softness</span><span class=\"val num\" data-lread=\"soft\"></span></div><input type=\"range\" data-lk=\"soft\" min=\"0.02\" max=\"1.5\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Intensity</span><span class=\"val num\" data-lread=\"power\"></span></div><input type=\"range\" data-lk=\"power\" min=\"0\" max=\"6\" step=\"0.01\" /></div>\n            <div class=\"field\" data-mcase=\"drift\"><div class=\"field-head\"><span class=\"name\">Travel</span><span class=\"val num\" data-lread=\"travel\"></span></div><input type=\"range\" data-lk=\"travel\" min=\"0\" max=\"1.5\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Colour flow</span><span class=\"val num\" data-lread=\"flow\"></span></div><input type=\"range\" data-lk=\"flow\" min=\"0\" max=\"4\" step=\"1\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Ambient</span><span class=\"val num\" data-lread=\"ambient\"></span></div><input type=\"range\" data-lk=\"ambient\" min=\"0\" max=\"0.6\" step=\"0.005\" /></div>\n            <div class=\"field\"><span class=\"name\">Seed</span>\n              <div class=\"row\"><div class=\"stepper\"><button data-lseed=\"-1\">\u2212</button><div class=\"vs\"></div><input type=\"number\" id=\"l-seed\" /><div class=\"vs\"></div><button data-lseed=\"1\">+</button></div><button class=\"icon-btn\" id=\"l-dice\" title=\"New light seed  (L)\" style=\"flex:0 0 38px\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 3h5v5M4 20L21 3M21 16v5h-5M15 15l6 6M4 4l5 5\"/></svg></button></div>\n            </div>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><rect x=\"8\" y=\"3\" width=\"8\" height=\"18\" rx=\"4\"/><path d=\"M11 6v12\" opacity=\".5\"/></svg><span class=\"lbl\">Surface</span></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Depth</span><span class=\"val num\" data-lread=\"depth\"></span></div><input type=\"range\" data-lk=\"depth\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Refraction</span><span class=\"val num\" data-lread=\"refract\"></span></div><input type=\"range\" data-lk=\"refract\" min=\"0\" max=\"3\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Gloss</span><span class=\"val num\" data-lread=\"gloss\"></span></div><input type=\"range\" data-lk=\"gloss\" min=\"0\" max=\"2\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Sharpness</span><span class=\"val num\" data-lread=\"sharp\"></span></div><input type=\"range\" data-lk=\"sharp\" min=\"1\" max=\"40\" step=\"0.5\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Edge colour</span><span class=\"val num\" data-lread=\"edgeTint\"></span></div><input type=\"range\" data-lk=\"edgeTint\" min=\"0\" max=\"3\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Rim light</span><span class=\"val num\" data-lread=\"rim\"></span></div><input type=\"range\" data-lk=\"rim\" min=\"0\" max=\"2\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Rim follows light</span><span class=\"val num\" data-lread=\"rimFollow\"></span></div><input type=\"range\" data-lk=\"rimFollow\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Rim width</span><span class=\"val num\" data-lread=\"rimW\"></span></div><input type=\"range\" data-lk=\"rimW\" min=\"0.3\" max=\"40\" step=\"0.1\" /></div>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><circle cx=\"12\" cy=\"12\" r=\"3.5\" fill=\"currentColor\"/><circle cx=\"12\" cy=\"12\" r=\"8\" opacity=\".35\"/></svg><span class=\"lbl\">Finish</span></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Bloom</span><span class=\"val num\" data-lread=\"bloom\"></span></div><input type=\"range\" data-lk=\"bloom\" min=\"0\" max=\"4\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Bloom threshold</span><span class=\"val num\" data-lread=\"bloomThr\"></span></div><input type=\"range\" data-lk=\"bloomThr\" min=\"0\" max=\"1.2\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Bloom size</span><span class=\"val num\" data-lread=\"bloomSize\"></span></div><input type=\"range\" data-lk=\"bloomSize\" min=\"0.3\" max=\"6\" step=\"0.05\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Black point</span><span class=\"val num\" data-lread=\"black\"></span></div><input type=\"range\" data-lk=\"black\" min=\"0\" max=\"0.9\" step=\"0.005\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">White point</span><span class=\"val num\" data-lread=\"white\"></span></div><input type=\"range\" data-lk=\"white\" min=\"0.2\" max=\"2\" step=\"0.005\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Contrast curve</span><span class=\"val num\" data-lread=\"curve\"></span></div><input type=\"range\" data-lk=\"curve\" min=\"0.5\" max=\"8\" step=\"0.05\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Saturation</span><span class=\"val num\" data-lread=\"sat\"></span></div><input type=\"range\" data-lk=\"sat\" min=\"0\" max=\"2.5\" step=\"0.01\" /></div>\n            <p class=\"note\">Crush the blacks with Black point + Contrast curve, let highlights burn with Bloom. White point below 1 pushes bright areas into pure light.</p>\n          </div>\n\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M3 8h18M3 16h18\"/><path d=\"M6 4v4M14 16v4\" /></svg><span class=\"lbl\">Atmosphere</span></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Spill</span><span class=\"val num\" data-lread=\"spill\"></span></div><input type=\"range\" data-lk=\"spill\" min=\"0\" max=\"1.2\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Sweep</span><span class=\"val num\" data-lread=\"sweep\"></span></div><input type=\"range\" data-lk=\"sweep\" min=\"0\" max=\"1.5\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Sweep width</span><span class=\"val num\" data-lread=\"sweepW\"></span></div><input type=\"range\" data-lk=\"sweepW\" min=\"0.02\" max=\"0.6\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Sweeps per loop</span><span class=\"val num\" data-lread=\"sweepN\"></span></div><input type=\"range\" data-lk=\"sweepN\" min=\"0\" max=\"6\" step=\"1\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Slice drift</span><span class=\"val num\" data-lread=\"slice\"></span></div><input type=\"range\" data-lk=\"slice\" min=\"0\" max=\"1\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Exposure</span><span class=\"val num\" data-lread=\"expo\"></span></div><input type=\"range\" data-lk=\"expo\" min=\"0.1\" max=\"12\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Contrast</span><span class=\"val num\" data-lread=\"gamma\"></span></div><input type=\"range\" data-lk=\"gamma\" min=\"0.4\" max=\"3\" step=\"0.01\" /></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Grain</span><span class=\"val num\" data-lread=\"grain\"></span></div><input type=\"range\" data-lk=\"grain\" min=\"0\" max=\"0.15\" step=\"0.001\" /></div>\n          </div>\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 3a9 9 0 0 1 0 18z\" fill=\"currentColor\" stroke=\"none\"/></svg><span class=\"lbl\">Palette \u00b7 lit</span></div>\n            <div class=\"field\"><span class=\"name\">Palette</span><div class=\"chips\" id=\"chips-pal\"></div></div>\n            <div class=\"swatch-row\">\n              <label><span class=\"name\">Light 1</span><input type=\"color\" data-pc=\"l0\" /></label>\n              <label><span class=\"name\">Light 2</span><input type=\"color\" data-pc=\"l1\" /></label>\n              <label><span class=\"name\">Light 3</span><input type=\"color\" data-pc=\"l2\" /></label>\n              <label><span class=\"name\">Light 4</span><input type=\"color\" data-pc=\"l3\" /></label>\n            </div>\n            <div class=\"swatch-row\">\n              <label><span class=\"name\">Edge</span><input type=\"color\" data-pc=\"edge\" /></label>\n              <label><span class=\"name\">Shadow</span><input type=\"color\" data-pc=\"shadow\" /></label>\n              <label><span class=\"name\">Background</span><input type=\"color\" data-pc=\"paper\" /></label>\n            </div>\n            <p class=\"note\">Each light source carries one of the four light colours. Edge tints silhouettes and rims, Shadow sits under the unlit parts of shapes, Background fills everything else.</p>\n          </div>\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 3v3M12 18v3\" opacity=\".5\"/></svg><span class=\"lbl\">Guides</span></div>\n            <div class=\"switch\"><span class=\"name\">Show light sources</span><div class=\"track-sw\" data-sw=\"showLights\"></div></div>\n            <p class=\"note\">Lighting applies to whatever you're making \u2014 type, icons, compositions and the Draw editor. Switch Flat / Lit at the top of the panel.</p>\n          </div>\n        </div>\n\n        <!-- \u2500\u2500 VIEW \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n        <div class=\"panel-grid\" data-tab-panel=\"view\" style=\"display:none\">\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 3a9 9 0 0 1 0 18z\" fill=\"currentColor\" stroke=\"none\"/></svg><span class=\"lbl\">Colour</span></div>\n            <div class=\"field\"><div class=\"field-head\"><span class=\"name\">Brand colours</span><button class=\"vbtn brand-edit-btn\" id=\"brand-edit\" title=\"Edit the palette\">Edit</button></div>\n              <div class=\"seg fill\" id=\"seg-btarget\" title=\"What a swatch click sets (\u21e7-click sets the other)\"><button data-v=\"paper\">Background</button><button data-v=\"ink\">Ink</button></div>\n              <div class=\"brand-sw\" id=\"brand-sw\"></div>\n              <div class=\"brand-pairs\" id=\"brand-pairs\"></div>\n              <div class=\"brand-editor hide\" id=\"brand-editor\">\n                <div id=\"brand-rows\"></div>\n                <div class=\"btn-row\"><button class=\"btn ghost sm\" id=\"brand-add\">+ Add colour</button><button class=\"btn ghost sm\" id=\"brand-reset\">Reset to file</button></div>\n                <button class=\"btn sm\" id=\"brand-export\" style=\"justify-content:center;width:100%\">Export brand-colors.js</button>\n                <p class=\"note\">Edits apply to all four Boldly tools in this browser at once. Export and replace <span class=\"kbd\">core/brand-colors.js</span> to make them the official palette.</p>\n              </div>\n            </div>\n            <div class=\"field\"><span class=\"name\">Theme</span>\n              <div class=\"chips\" id=\"chips-theme\"></div>\n            </div>\n            <div class=\"swatch-row\">\n              <label><span class=\"name\">Paper</span><input type=\"color\" id=\"c-paper\" /></label>\n              <label><span class=\"name\">Ink</span><input type=\"color\" id=\"c-ink\" /></label>\n            </div>\n          </div>\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M3 9h18M3 15h18M9 3v18M15 3v18\"/></svg><span class=\"lbl\">Overlays</span></div>\n            <div class=\"switch\"><span class=\"name\">Unit grid</span><div class=\"track-sw\" data-sw=\"grid\"></div></div>\n            <div class=\"switch\"><span class=\"name\">Metric lines</span><div class=\"track-sw\" data-sw=\"metrics\"></div></div>\n            <div class=\"switch\"><span class=\"name\">Construction</span><div class=\"track-sw\" data-sw=\"constr\"></div></div>\n            <div class=\"switch\"><span class=\"name\">Outline</span><div class=\"track-sw\" data-sw=\"outline\"></div></div>\n          </div>\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/><path d=\"M3 9h18\"/></svg><span class=\"lbl\">Frame</span></div>\n            <div class=\"field\"><span class=\"name\">Size</span>\n              <div class=\"hty-select\" data-size-preset>\n                <button class=\"hty-select-btn\"><span class=\"hty-select-val\">1920 \u00d7 1080 \u00b7 16:9</span><svg class=\"hty-select-chev\" viewBox=\"0 0 12 8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M1 2l5 4 5-4\"/></svg></button>\n                <div class=\"hty-select-menu\" role=\"listbox\">\n                  <button class=\"hty-opt\" data-value=\"1080x1080\">1080 \u00d7 1080 \u00b7 1:1</button>\n                  <button class=\"hty-opt\" data-value=\"1080x1350\">1080 \u00d7 1350 \u00b7 4:5</button>\n                  <button class=\"hty-opt\" data-value=\"1080x1440\">1080 \u00d7 1440 \u00b7 3:4</button>\n                  <button class=\"hty-opt\" data-value=\"1080x1920\">1080 \u00d7 1920 \u00b7 9:16</button>\n                  <button class=\"hty-opt is-selected\" data-value=\"1920x1080\">1920 \u00d7 1080 \u00b7 16:9</button>\n                  <button class=\"hty-opt\" data-value=\"2048x2048\">2048 \u00d7 2048 \u00b7 1:1</button>\n                  <button class=\"hty-opt\" data-value=\"custom\">Custom\u2026</button>\n                </div>\n              </div>\n            </div>\n            <div class=\"tf-row\" data-size-custom style=\"display:none;\">\n              <label class=\"tf\"><span class=\"g\">W</span><input type=\"number\" data-size=\"w\" data-scrub=\"2\" data-min=\"1\" data-step=\"1\" value=\"1920\"/></label>\n              <label class=\"tf\"><span class=\"g\">H</span><input type=\"number\" data-size=\"h\" data-scrub=\"2\" data-min=\"1\" data-step=\"1\" value=\"1080\"/></label>\n            </div>\n          </div>\n        </div>\n\n        <!-- \u2500\u2500 EXPORT \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n        <div class=\"panel-grid\" data-tab-panel=\"export\" style=\"display:none\">\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"2\"/><path d=\"M7 4v16M17 4v16M3 9h4M3 15h4M17 9h4M17 15h4\"/></svg><span class=\"lbl\">Motion \u00b7 MP4</span></div>\n            <div class=\"field\"><span class=\"name\">Frame rate</span>\n              <div class=\"seg fill\" id=\"seg-fps\"><button data-v=\"24\">24</button><button data-v=\"30\">30</button><button data-v=\"60\">60</button></div>\n            </div>\n            <div class=\"field\"><span class=\"name\">Loops</span>\n              <div class=\"seg fill\" id=\"seg-loops\"><button data-v=\"1\">1\u00d7</button><button data-v=\"2\">2\u00d7</button><button data-v=\"3\">3\u00d7</button></div>\n            </div>\n            <div class=\"field-head\"><span class=\"name\">Clip</span><span class=\"val num\" id=\"x-clip\"></span></div>\n            <button class=\"btn sm\" id=\"x-mp4\" style=\"justify-content:center\">Export MP4</button>\n            <div class=\"progress\"><i id=\"x-prog\"></i></div>\n            <p class=\"note\">Frame-exact H.264 (24 Mbps CBR, key every 2s). Every chunk is decoded while encoding, so a broken stream never gets saved. The loop is seamless: last frame flows into the first.</p>\n          </div>\n          \n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"2\"/><circle cx=\"8.5\" cy=\"9.5\" r=\"1.5\"/><path d=\"M21 16l-5-5L5 20\"/></svg><span class=\"lbl\">Image</span></div>\n            <div class=\"field\"><span class=\"name\">PNG resolution</span>\n              <div class=\"seg fill\" id=\"seg-mult\"><button data-v=\"1\">1\u00d7</button><button data-v=\"2\">2\u00d7</button><button data-v=\"4\">4\u00d7</button></div>\n            </div>\n            <div class=\"switch\"><span class=\"name\">Transparent background</span><div class=\"track-sw\" data-sw=\"xTransparent\"></div></div>\n            <div class=\"switch\"><span class=\"name\">Include overlays</span><div class=\"track-sw\" data-sw=\"xOverlays\"></div></div>\n            <div class=\"btn-row\"><button class=\"btn ghost sm\" id=\"x-png\">PNG</button><button class=\"btn sm\" id=\"x-svg\">SVG</button></div>\n            <p class=\"note\">SVG is pure vector: one closed path per letter, arcs kept as true arcs.</p>\n          </div>\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><path d=\"M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z\"/><path d=\"M14 3v6h6\"/></svg><span class=\"lbl\">Type system</span></div>\n            <p class=\"note\">Glyphs + form settings as one JSON file \u2014 the source for the pattern and motion tools to come.</p>\n            <div class=\"btn-row\"><button class=\"btn ghost sm\" id=\"x-json\">Save .json</button><button class=\"btn ghost sm\" id=\"x-load\">Load .json</button></div>\n            <button class=\"btn sm\" id=\"x-link\" style=\"justify-content:center\">Autosave to file\u2026</button>\n            <p class=\"note num\" id=\"x-store\"></p>\n          </div>\n          <div class=\"group\">\n            <div class=\"group-h\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 12a9 9 0 1 0 3-6.7L3 8\"/><path d=\"M3 3v5h5M12 7v5l3 2\"/></svg><span class=\"lbl\">Saved versions</span></div>\n            <button class=\"btn ghost sm\" id=\"x-find\" style=\"justify-content:center\">Find saved versions</button>\n            <div id=\"x-versions\" style=\"display:flex;flex-direction:column;gap:8px\"></div>\n            <input type=\"file\" id=\"x-file\" accept=\".json,application/json\" class=\"hide\" />\n            <button class=\"btn ghost sm\" id=\"x-merge\" style=\"justify-content:center\">Merge .json files as variants\u2026</button>\n            <input type=\"file\" id=\"x-mfile\" accept=\".json,application/json\" multiple class=\"hide\" />\n            <button class=\"btn ghost sm\" id=\"x-reset\" style=\"justify-content:center\">Reset all glyphs to default</button>\n          </div>\n        </div>\n\n      </div>\n    </div>\n\n    <div class=\"hty-main\">\n      <div class=\"hty-chip\"><div class=\"nm\">Boldly Identity</div><div class=\"lbl\">Type \u00b7 icons \u00b7 compositions \u00b7 flat + lit</div></div>\n      <div class=\"main-row\">\n        <button class=\"icon-btn\" id=\"b-undo\" title=\"Undo  \u2318Z\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 7v6h6\"/><path d=\"M3 13a9 9 0 1 0 3-7.7L3 8\"/></svg></button>\n        <button class=\"icon-btn\" id=\"b-redo\" title=\"Redo  \u21e7\u2318Z\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 7v6h-6\"/><path d=\"M21 13a9 9 0 1 1-3-7.7L21 8\"/></svg></button>\n        <button class=\"btn\" id=\"b-export\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 15V3m0 12l-4-4m4 4l4-4M5 15v4a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-4\"/></svg>Export SVG</button>\n      </div>\n    </div>\n  </div>\n\n");
